/// <reference lib="webworker" />
import { clientsClaim } from 'workbox-core'
import { cleanupOutdatedCaches, createHandlerBoundToURL, precacheAndRoute } from 'workbox-precaching'
import { NavigationRoute, registerRoute } from 'workbox-routing'
import { NetworkOnly } from 'workbox-strategies'

declare let self: ServiceWorkerGlobalScope

self.skipWaiting()
clientsClaim()

// Precache assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST)

// Clean up old caches
cleanupOutdatedCaches()

// SPA fallback for navigation requests
const denylist = [/^\/api\//, /^\/rest\//, /^\/auth\//]
registerRoute(
  new NavigationRoute(createHandlerBoundToURL('index.html'), { denylist })
)

// Never cache Supabase API requests
registerRoute(
  ({ url }) => url.href.includes('supabase.co'),
  new NetworkOnly()
)

// --- Push Notifications ---

self.addEventListener('push', (event) => {
  if (!event.data) return

  try {
    const payload = event.data.json()
    
    event.waitUntil(
      self.registration.showNotification(payload.title, {
        body: payload.body,
        icon: '/icons/icon-192x192.png',
        badge: '/favicon.svg',
        data: payload.data || {},
        actions: payload.actions || [],
        requireInteraction: true,
      } as any)
    )
  } catch (err) {
    console.error('[SW] Error parsing push data', err)
  }
})

// Helper to get access token from IndexedDB (synced from frontend)
async function getAccessToken() {
  return new Promise<string | null>((resolve) => {
    const request = indexedDB.open('supabase-auth')
    request.onsuccess = (e) => {
      const db = (e.target as IDBOpenDBRequest).result
      if (!db.objectStoreNames.contains('tokens')) return resolve(null)
      const tx = db.transaction('tokens', 'readonly')
      const store = tx.objectStore('tokens')
      const getReq = store.get('access_token')
      getReq.onsuccess = () => resolve(getReq.result || null)
      getReq.onerror = () => resolve(null)
    }
    request.onerror = () => resolve(null)
  })
}

self.addEventListener('notificationclick', (event) => {
  event.notification.close()

  const data = event.notification.data || {}
  const action = event.action

  if (action && data.actionUrl) {
    // Action button clicked (e.g., Accept/Reject)
    event.waitUntil(
      (async () => {
        try {
          const token = await getAccessToken()
          if (!token) {
            // Fallback: open app if no token is available for background request
            return self.clients.openWindow(data.url || '/')
          }
          
          let bodyObj = data.bodyPayload || { action, ...data }
          if (data.actionBodyMap && data.actionBodyMap[action]) {
            bodyObj = data.actionBodyMap[action]
          }

          await fetch(data.actionUrl, {
            method: data.method || 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`,
              ...(data.headers || {})
            },
            body: JSON.stringify(bodyObj)
          })

          // Optionally, notify open clients to refresh data
          const windowClients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
          for (const client of windowClients) {
            client.postMessage({ type: 'PUSH_ACTION_COMPLETED', action, data })
          }
        } catch (err) {
          console.error('[SW] Action failed in background', err)
          // Fallback to opening the app on failure
          self.clients.openWindow(data.url || '/')
        }
      })()
    )
  } else {
    // Normal click on notification body — focus existing window or open new one
    event.waitUntil(
      self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients: any) => {
        for (const client of windowClients) {
          if (client.url.includes(self.registration.scope) && 'focus' in client) {
            client.postMessage({ type: 'NOTIFICATION_CLICKED', data })
            return client.focus()
          }
        }
        return self.clients.openWindow(data.url || '/')
      })
    )
  }
})
